package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	_ "github.com/shopspring/decimal"
)

// 01 DATE-REC, 12 bytes
type DateRec struct {
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsLeapFlag string = "N" // PIC X len=1 = "N"
var WsQ int64 = 0        // PIC 9(4) len=4 = 0
var WsR4 int64 = 0       // PIC 9(3) len=3 = 0
var WsR100 int64 = 0     // PIC 9(3) len=3 = 0
var WsR400 int64 = 0     // PIC 9(3) len=3 = 0
var WsMaxDay int64 = 0   // PIC 99 len=2 = 0
var WsValid int64 = 0    // PIC 99 len=2 = 0
var WsBadMonth int64 = 0 // PIC 99 len=2 = 0
var WsBadDay int64 = 0   // PIC 99 len=2 = 0

// additional state
var curRec DateRec
var scanner *bufio.Scanner

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func formatPic9(v int64, digits int) string {
	mod := pow10(digits)
	// keep low-order digits (high-order dropped)
	t := v % mod
	if t < 0 {
		t = -t
	}
	s := fmt.Sprintf("%0*d", digits, t)
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	return s
}

func normalizeLine(line string) string {
	if len(line) < 12 {
		return line + strings.Repeat(" ", 12-len(line))
	}
	if len(line) > 12 {
		return line[:12]
	}
	return line
}

func parseNumeric(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	// s should be digits only; if parse fails treat as 0
	v, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		// try to handle sign or embedded spaces: extract digits
		// fallback: keep only digits prefix
		return 0
	}
	return v
}

func ReadPara() {
	if scanner.Scan() {
		line := scanner.Text()
		recStr := normalizeLine(line)
		curRec.DtId = recStr[0:4]
		curRec.DtYyyy = parseNumeric(recStr[4:8])
		curRec.DtMm = parseNumeric(recStr[8:10])
		curRec.DtDd = parseNumeric(recStr[10:12])
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func LeapPara() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	WsQ = (curRec.DtYyyy / 4) % pow10(4)
	WsR4 = curRec.DtYyyy % 4
	WsR4 = WsR4 % pow10(3)
	if WsR4 < 0 {
		WsR4 = -WsR4
	}
	// DIVIDE DT-YYYY BY 100 GIVING WS-Q REMAINDER WS-R100
	WsQ = (curRec.DtYyyy / 100) % pow10(4)
	WsR100 = curRec.DtYyyy % 100
	WsR100 = WsR100 % pow10(3)
	if WsR100 < 0 {
		WsR100 = -WsR100
	}
	// DIVIDE DT-YYYY BY 400 GIVING WS-Q REMAINDER WS-R400
	WsQ = (curRec.DtYyyy / 400) % pow10(4)
	WsR400 = curRec.DtYyyy % 400
	WsR400 = WsR400 % pow10(3)
	if WsR400 < 0 {
		WsR400 = -WsR400
	}
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	switch curRec.DtMm {
	case 2:
		if WsLeapFlag == "Y" {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
	// store truncation for PIC 99 (not needed but mimic)
	WsMaxDay = WsMaxDay % pow10(2)
}

func ProcessPara() {
	LeapPara()
	if curRec.DtMm < 1 || curRec.DtMm > 12 {
		WsBadMonth = (WsBadMonth + 1) % pow10(2)
		fmt.Printf("%s BAD MONTH %s\n", curRec.DtId, formatPic9(curRec.DtMm, 2))
	} else {
		DaysPara()
		if curRec.DtDd < 1 || curRec.DtDd > WsMaxDay {
			WsBadDay = (WsBadDay + 1) % pow10(2)
			fmt.Printf("%s BAD DAY %s MAX %s\n", curRec.DtId, formatPic9(curRec.DtDd, 2), formatPic9(WsMaxDay, 2))
		} else {
			WsValid = (WsValid + 1) % pow10(2)
			fmt.Printf("%s VALID %s-%s-%s\n", curRec.DtId, formatPic9(curRec.DtYyyy, 4), formatPic9(curRec.DtMm, 2), formatPic9(curRec.DtDd, 2))
		}
	}
	ReadPara()
}

func main() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()

	scanner = bufio.NewScanner(f)
	// allow larger lines if needed
	const maxCapacity = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, maxCapacity)

	// MAIN-PARA
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	// CLOSE DATE-FILE is deferred
	fmt.Printf("VALID: %s BAD MONTH: %s BAD DAY: %s\n", formatPic9(WsValid, 2), formatPic9(WsBadMonth, 2), formatPic9(WsBadDay, 2))
}
